class Solution {
    public int concatenatedBinary(int n){
        final int MOD=1_000_000_007;
        long answer=0;
        int bits=0;
        for(int value=1;value<=n;value++){
            if((value&(value-1))==0)bits++;
            answer=((answer<<bits)+value)%MOD;
        }
        return (int)answer;
    }
}

code.kotlin:
class Solution {
    fun concatenatedBinary(n:Int):Int{
        val mod=1_000_000_007L;
        var answer=0L;
        var bits=0;
        for(value in 1..n){
            if(value and (value-1)==0)bits++;
            answer=((answer shl bits)+value)%mod
        };
        return answer.toInt()
    }
}

code.cpp:
class Solution {
    public: int concatenatedBinary(int n){
        const int MOD=1000000007;
        long long answer=0;
        int bits=0;
        for(int value=1;value<=n;++value){
            if(!(value&(value-1)))++bits;
            answer=((answer<<bits)+value)%MOD;
        }
        return answer;
    }
};
